// Helper function to check if a number is a power of two (though not used in the main solution)
fn is_2_pow(n: i32) -> bool {
    n > 0 && (n & (n - 1)) == 0
}

// Binary search helper that finds the lower bound (insertion position) in a sorted range
fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    let mut lo = lo;
    let mut hi = hi;
    
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] < x {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    
    lo
}

// Main function that finds the insertion position within the first 1000 elements
fn search_1000(a: &[i32], x: i32) -> usize {
    // Ensure we only consider the first 1000 elements
    let n = a.len().min(1000);
    
    // Use the helper function to perform binary search on the range [0, n)
    search_range_helper(a, x, 0, n)
}